add('jp-fuji-hiking','富士山五合目登山入門：裝備、交通與注意事項完整指南','fuji,mount,登山,japan',['富士山','登山','一日遊'],'富士山是日本最高的山峰（3,776公尺），也是日本最具代表性的地標。每年7月至9月登山季開放期間，數十萬名登山者湧向五合目Starting Point，挑戰登顶。', '登山季：7月初～9月上旬；賞櫻：4月底～5月初',[('六合目御殿場口登山口','御殿場線從東京出發約2小時，是登頂人數最多的路線。'),('五合目停車區','可搭乘巴士或自駕抵達，有廁所、輕食攤位和紀念品店。'),('山頂雷峰','海拔3,776公尺的終點，立有三角點石碑。日出時分的鑽石富士是全世界攝影師夢寐以求的畫面。'),('北口大避難小屋','六合目與七合目之間的重要中繼站，提供簡易餐點和休息空間。旺季需提前預約。'),('富士河口湖','下山後必去的景點，湖面對稱倒映富士山的景色是經典拍照角度。')],[('溫泉蛋','大湧谷的硫磺泉煮出的雞蛋，一顆入魂，傳說吃一個增加七年壽命。'),('御好燒','登山口附近的街頭小吃，熱騰騰的餅皮加高麗菜和麵糊，補充體力的最佳選擇。'),('秩父牛涮涮鍋','山梨縣鄰近的秩父牛是日本三大和牛之一，下山後推薦來一鍋溫暖身心。')],{'交通':'約1,200-2,500元','餐飲':'約1,500-3,000元','合計':'約3,500-7,000元'},[('需要登山經驗嗎？','五合目路線屬於輕登山，無經驗者也能挑戰。但需具備基本體力，建議平時先做有氧訓練。'),('網路問題？','山中信号極弱或完全無訊號，務必出發前下載離線地圖，並攜帶行動電源。')])

add('jp-tokyo-shibuya','東京澀谷全攻略：Shibuya Crossing、宮下公園與潮流文化深度探索','tokyo,shibuya,japan',['東京','澀谷','購物'],'澀谷是日本潮流文化的發源地，也是全世界最繁忙的十字路口所在地。每年數百萬旅客穿越這著名的澀谷十字路口，感受東京的脈動。', '全年適宜；櫻花季3月底～4月中旬',[('澀谷十字路口','全球最繁忙的人行穿越道，每次綠燈約300人同時穿過。推薦到Starbucks二樓或Shibuya Sky觀景台俯瞰全景。'),('宮下公園（MIYASHITA PARK）','2020年開幕的複合型商業設施，屋頂公園可賞櫻，地下街有40+店家。'),('忠犬八公像','澀谷車站西出口的象徵，約會碰頭地點。'),('神南地區巷弄','繞開主街進入後巷，發現隱藏的爵士酒吧、復古二手店和東京人私藏的拉麵店。')],[('一蘭拉麵澀谷店','24小時營業的個人座間籠拉麵，適合時差調整期的夜貓子。'),('Blue Bottle Coffee','宮下公園內的藍瓶咖啡，拿鐵配上東京天際線是完美的午後。')],{'交通':'約500-1,000元','餐飲':'約2,000-4,000元','合計':'約3,000-6,000元'},[('從機場怎麼去？','成田機場搭Skyliner到上野轉山手線約90分鐘；羽田機場搭TX到品川轉山手線約40分鐘。'),('需要使用日幣現金嗎？','大部分店家接受信用卡和PayPay，但老鋪拉麵店和市場仍只收現金，建議準備2-3萬日元。')])

add('jp-kyoto-fushimi','京都伏見稻荷大社全攻略：千本鳥居的最佳走法與秘境攻略','kyoto,fushimi,inari,japan',['京都','神社','景點','攝影'],'伏見稻荷大社是日本三萬座稻荷神社的總本宮，以千本鳥居聞名世界。朱紅色的鳥居隧道沿山勢綿延數十公里，是京都最具代表性的景觀之一。', '全年適宜；最佳攝影時段：清晨6-7點或傍晚4-5點',[('千本鳥居主參道','從本殿到山頂約2公里的鳥居隧道，越往上走人潮越少，建議至少走到稲荷山山頂（约40分鐘）。'),('本殿與拝殿','入口處的壯麗朱紅建築，清晨人最少，是拍攝無人鳥居的黃金時間。'),('御本宮神社後的隱藏小路','多數遊客不會走的岔路，通往較少人知的 smaller 鳥居群和茶屋，寧靜又有氛圍。')],[('油豆富','伏見稻荷的定番伴手禮，薄薄炸豆腐皮包裹飯糰，只有當地賣得到。'),('稻荷壽司','因神社命名而來的經典料理，甜炸豆腐皮包裹醋飯，是京都的代表性便當。'),('宇治抹茶甜品','附近的宇治是抹茶產地，推荐抹茶冰淇淋和抹茶千層蛋糕。')],{'交通':'約400-800元','餐飲':'約1,500-3,000元','合計':'約2,500-5,000元'},[('什麼時候去人最少？','平日清晨6:30-7:30是人數最少的時段，週末早上9點後人潮明顯增多。'),('需要門票嗎？','完全免費！鳥居全部開放，建議自備水和零食。')])

add('jp-osaka-doton','大阪道頓堀＆美國村美食全攻略：從一蘭拉麵到黑門市場的必吃地圖','osaka,dotonbori,japan,food',['大阪','美食','購物','夜景'],'大阪被稱為日本的廚房，道頓堀是其中最璀璨的美食天堂。霓虹燈招牌、沿街攤販、米其林星級餐廳應有盡有。', '全年適宜；夏季（7-8月）有天神祭煙火',[('道頓堀河畔','格力高跑者招牌是大阪地標，沿河散步欣賞霓虹燈光是必備體驗。晚上8點後燈光最璀璨。'),('美國村','大阪的原宿，街頭表演、潮流品牌、復古二手店聚集地。'),('黑門市場','被稱為大阪的廚房，新鮮海鮮、和牛串燒、現開生蠔，可以边走边吃逛2小時。')],[('元祖串炸達摩','大阪串炸的始祖店，裹著酥脆麵衣的肉串配捲心菜是經典吃法。'),('黑門市場現烤和牛串','汁水飽滿的和牛串燒，現場烤製香氣四溢。'),('法善寺橫丁','充滿懷舊氛圍的小巷，炭火燒肉和烏龍麵小店隱藏其中。')],{'交通':'約500-1,000元','餐飲':'約3,000-6,000元','合計':'約4,000-8,000元'},[('大阪周遊卡值得買嗎？','如果計劃逛5個以上景點非常值得，包含交通和20個景點免費入場。')])

add('jp-nara-deer','奈良公園完整攻略：餵鹿秘訣、東大寺大佛與春日大社一日遊','nara,deer,japan,temple',['奈良','鹿','景點','一日遊'],'奈良公園擁有超過1,200隻野生梅花鹿，是日本國家天然紀念物。東大寺的世界最大木造建築和大佛坐像更是震撼。', '全年適宜；櫻花季3月底～4月初（西公園最美）；紅葉季11月中旬～12月初',[('奈良公園餵鹿','購買80日幣的鹿仙貝餵鹿，注意鹿會磕頭討食，部分鹿會用角頂人，請握住鹿角底部以免被頂。'),('東大寺大佛殿','世界最大木造建築，內部供奉高15公尺的盧舍那大佛，震撼程度親眼見證才懂。'),('春日大社','千盞石燈籠沿參道排列的神社，是日本最重要的神社之一。'),('若草山','奈良公園旁的扇形山丘，可乘缆車上山俯瞰奈良盆地。')],[('鹿價壽司','奈良百年老店，用鹿肉做的壽司是日本獨有的體驗。'),('柿葉壽司','奈良傳統保存食品，用柿葉包裹醋飯和新鮮魚類。'),('桶餅','春日大社參道旁的限定甜品，軟糯糯米餅淋上煉乳。')],{'交通':'約800-1,500元','餐飲':'約1,500-3,000元','門票':'約1,000元','合計':'約3,500-6,000元'},[('餵鹿要注意什麼？','鹿仙貝買好後先藏起來，等鹿靠近再拿出來餵。不要奔跑或舉起手機太久，鹿會以為你要追牠們。'),('一天夠嗎？','一天時間足夠走訪主要景點，建議早上8點前到達以避開人潮。')])

add('jp-hokkaido-snow','北海道滑雪全攻略：二世谷粉雪、札幌白色燈節與定禪寺雪壁祭','hokkaido,snow,ski,japan',['北海道','滑雪','冬季','溫泉'],'北海道是日本冬季最精彩的目的地，二世谷被譽為粉雪天堂，札幌白色燈節和定禪寺雪壁祭每年吸引百萬遊客。', '12月中旬～3月中旬（滑雪季最佳：1-2月）',[('二世谷BLUFF滑雪場','世界級粉雪滑雪場，年積雪量達15公尺，被SKI期刊評為全球最佳滑雪場之一。'),('札幌白色燈節','每年2月在大通公園舉辦，數萬根燭光與LED燈打造梦幻燈海。'),('定禪寺雪壁祭','街道上堆疊的巨型雪牆雕刻成各種造型，夜晚點燈後如同童話世界。'),('定山溪溫泉','札幌郊區的最古老溫泉鄉，雪中之湯是北海道独有的體驗。')],[('札幌味噌拉麵','濃厚湯頭的札幌在地拉麵店。'),('成吉思汗烤肉','北海道發明的高考羊肉，煙燻香氣十足。'),('海鮮丼','小樽寿司市場的新鮮海鮮丼，海膽、鮭魚卵、甜蝦一次滿足。')],{'交通':'約3,000-6,000元','餐飲':'約3,000-5,000元','滑雪裝備':'約1,500-3,000元','合計':'約8,000-15,000元'},[('新手適合去哪個滑雪場？','新雪谷（Niseko）和留壽都（Rusutsu）都有 beginner 專屬坡道。'),('冬天去北海道需要准备什麼？','保暖內衣+羊毛襪+防風外套是基本，手套和圍巾必備，手機容易凍關機請備暖貼。')])

add('jp-hakone-onsen','箱根溫泉一日遊：火山地形、蘆之湖舟遊與免費美術館完整攻略','hakone,onsen,japan',['箱根','溫泉','一日遊','景點'],'箱根是日本最著名的溫泉鄉，位於富士箱根伊豆國立公園內。大湧谷的硫磺煙氣、蘆之湖的海盗船、強羅公園的噴泉。', '全年適宜；紅葉季11月中下旬蘆之湖美景絕佳',[('大湧谷','火山爆發形成的谷地，硫磺煙氣裊裊，地上煮蛋是必體驗（據說吃一個加七年壽命）。'),('蘆之湖海上巡禮','搭乘海盗船遊覽蘆之湖，天氣好時可遠望富士山倒映湖面。'),('箱根神社','湖中的朱紅色鳥居是日本三大奇勝之一。'),('強羅公園','免門票的日式庭園，四季花緻不同。')],[('黑雞蛋','大湧谷特產，硫化鐵滲入蛋壳使其變黑，口感Q彈帶有礦物風味。'),('蕎麥麵','箱根深山中的手工蕎麥麵，現點現做口感獨特。')],{'交通':'約1,500-3,000元','餐飲':'約2,000-4,000元','溫泉入湯':'約2,000-5,000元','合計':'約5,500-12,000元'},[('箱根周遊券值得買嗎？','如果計劃玩3天以上非常值得，包含地鐵、船、纜車等交通。'),('從東京怎麼去？','搭小田急線浪漫特快約85分鐘到箱根湯本。')])

add('jp-nikko-tobu','日光東照宮全攻略：世界文化遺產陽明門的金色輝煌與周邊溫泉','nikko,to-shogu,japan,unesco',['日光','世界遺產','神社','溫泉'],'日光東照宮是日本最華麗的神社之一，1999年列為世界文化遺產。陽明門的金色雕刻和三猿浮雕是鎮館之寶。', '4-5月櫻花、10-11月紅葉；溫泉季全年適宜',[('陽明門','東照宮的正門，金色雕刻繁複華麗，三隻猴子雕塑（不看不聽不說）是必拍景點。'),('神厩神社（馬舍）','朱紅色建築倒映在池塘中，是日光最著名的拍照角度。'),('輪王寺','與東照宮相鄰的佛教寺院，三重塔和勅使門是重要文化財。'),('中禪寺湖','火山口湖，湖畔的環湖步道適合輕鬆散步。'),('華嚴瀑布','日本三大瀑布之一，落差97公尺。')],[('湯波','日光特產，豆皮熬煮成薄膜狀，口感滑嫩。'),('栗子甜品','秋季限定的栗子蛋糕和栗子蒙布朗。')],{'交通':'約2,000-4,000元','餐飲':'約2,000-3,500元','門票':'約2,500元','合計':'約6,500-11,000元'},[('從東京怎麼去？','搭JR特急華嚴號約2小時，或搭TSUKUBA EXPRESS到淺草轉東武線約1.5小時。')])

add('jp-okinawa','沖繩那霸＆美ら海水族館全攻略：離島跳島、海之翼與琉球文化','okinawa,chaura+aquarium,japan,island',['沖繩','海灘','水族館','離島'],'沖繩是日本的南端天堂，擁有白沙碧海和獨特的琉球文化。美ら海水族館是世界級的水族館。', '5-10月（海水最藍）；11-3月適合賞鯨',[('美ら海水族館','世界最大級水族館之一，水槽深度達5公尺，鲸鯊和蝠鱝在眼前游過是震撼體驗。'),('青洞＆青之洞窟','透明度極高的海水洞穴，浮潛可見色彩斑斕的熱帶魚群。'),('殘波岬燈塔','沖繩最西端的燈塔，日落時分景色絕美。'),('首里城公園','琉球王國的皇城遺址，2019年火災後正在重建中。')],[('琉球玻璃詩歌（ゴーヤーチャンプルー）','苦瓜炒蛋是沖繩家庭料理代表。'),('阿古豬炸豬排','沖繩在地黑豬製成的炸豬排，肉質鮮嫩多汁。'),('紅芋甜品','沖繩是日本紅薯最大產區，紅芋冰淇淋不可錯過。')],{'交通':'約3,000-6,000元','餐飲':'約2,500-4,500元','活動':'約2,000-5,000元','合計':'約8,000-16,000元'},[('跳島活動要預約嗎？','熱門島嶼建議提前3-7天預約，週末更需早訂。'),('海水溫度如何？','5-10月海水溫度26-29°C，適合浮潛和潛水。')])

# KOREA
add('kr-seoul-naksan','首爾南山南山堂＆南山的樹木園：首爾夜景最佳拍攝點攻略','seoul,namsan+tower,korea,night',['首爾','南山','夜景','告白鎖'],'南山是首爾的象徵，南山塔（N Seoul Tower）高236公尺，是首爾最浪漫的約會地點。', '全年適宜；櫻花季4月南山道路櫻花隧道絕美',[('南山塔告白鎖','情侶們在欄杆上掛上愛的鎖，象徵永恆愛情。建議工作日去，周末人滿為患。'),('南山樹木園','1940年代建於南山上的植物园，遊客稀少但景色優美。'),('南山公園纜車','從明洞出發搭纜車約10分鐘上山，夕陽時分的景色最值得體驗。')],[('明洞韓式炸雞','甜辣醬和芝士粉是經典組合。'),('廣藏市場拌飯','首爾最古老的市場，現做的拌飯和鮮榨果汁。')],{'交通':'約3,000-6,000元','餐飲':'約2,000-4,000元','活動':'約1,500-3,000元','合計':'約6,500-13,000元'},[('從明洞怎麼去南山？','搭地鐵2號線到東大門歷史文化公園站轉4號線到市廳站，再轉南山纜車。'),('什麼時候去夜景最美？','日落的藍調時刻（天快黑未黑時）拍攝效果最好。')])

add('kr-busan-haeundae','釜山海雲台海灘全攻略：半月沙灘、札嘎其市場與龍頭山夜市','busan,haeundae+beach,korea,summer',['釜山','海灘','美食','夜市'],'釜山是韓國第二大城市，擁有世界上最密集的海灘之一。海雲台是釜山最知名的海灘。', '6-9月（海灘季）；10-11月海鮮最肥美',[('海雲台沙灘','釜山最負盛名的沙灘，夏季每天有數十萬人來此戲水。'),('札嘎其市場','韓國最繁忙的水產市場，活跳蚤蝦和生魚片是一絕。'),('龍頭山公園','海雲台入口的公園，龍頭山塔的觀景台可俯瞰整個海雲台海岸線。')],[('活蝦生魚片','札嘎其市場的招牌，新鮮活蝦處理後直接食用。'),('海雲台海鮮麵','沿海雲台海岸線的著名海鮮麵店。')],{'交通':'約2,000-4,000元','餐飲':'約2,000-4,000元','住宿':'約3,000-8,000元','合計':'約7,000-16,000元'},[('海雲台和札嘎其市場遠嗎？','從海雲台搭地鐵到札嘎其市場約15分鐘。')])

add('kr-jeju-hallasan','濟州島漢拏山登山全攻略：涉嵯口、御前稜線與山頂天池碧玉潭','jeju,hallasan+volcano+korea',['濟州島','漢拏山','登山','自然'],'漢拏山是韓國最高峰（1,947公尺），也是一座休眠火山。山頂的天池（池潤潭）是韓國最神聖的湖泊之一。', '5-10月（登山季）；11-4月部分路線封閉',[('涉嵯口Starting Point','最熱門的登山路線起點，海拔1,000公尺處有觀景台，全程約4-5小時登顶。'),('池潤潭','火山口湖，深邃的藍綠色湖水令人屏息。'),('白鹿潭','漢拏山另一端的瀑布，从車緩站可輕鬆到達。'),('城山日出峰','濟州島另一大地標，UNESCO世界自然遺產。')],[('黑豬肉燒烤','濟州島特產的黑豬肉，質地柔軟且無腥味。'),('海蔘生魚片','濟州島的海蔘新鮮度冠絕韓國。'),('橘仔茶','濟州島特產的柑橘茶，暖胃又提神。')],{'交通':'約5,000-10,000元','餐飲':'約2,500-4,500元','裝備':'約1,000-2,000元','合計':'約8,500-17,000元'},[('需要登山經驗嗎？','涉嵯口路線對初学者友好，但需具備基礎體力。建議每天步行8,000步以上再嘗試。')])

add('kr-gyeongju','慶州半日遊：皇龍寺八層石塔、雁鸭池與慶州國立博物館完美行程','gyeongju,temple+korea+silla',['慶州','歷史','廟宇','世界遺產'],'慶州是新羅王朝1,000年的首都，被稱為沒有屋頂的博物館。城內散落著127處歷史遺跡。', '4月櫻花、10月紅葉；全年適宜',[('皇龍寺址八層石塔','新羅時代的八層石塔遺址，是韓國現存最古老的石塔之一。'),('雁鸭池（안압지）','新羅王宮的別殿池塘，夜晚點燈後的美景是慶州最浪漫的場景。'),('慶州國立博物館','收藏了新羅王朝最精美的文物。'),('月精橋','夜晚點燈的月亮形狀拱橋，倒影在池中非常夢幻。')],[('慶州牛肉湯','慶州特產的牛肉湯飯，湯頭清澈但味道深厚。'),('黃海南道炒年糕','甜辣適中，是韓劇大長今的同款味道。')],{'交通':'約1,500-3,000元','餐飲':'約1,500-2,500元','門票':'約800-1,500元','合計':'約4,000-7,000元'},[('穿韓服有優惠嗎？','穿韓服參觀大部分景點免門票，慶州市區有多家韓服租賃店。')])

# TAIWAN
add('tw-taipei-101','台北101觀景台＆信義區美食全攻略：跨年煙火、世界最快速電梯與隱藏咖啡廳','taipei,101+tower+taiwan',['台北','101','購物','美食'],'台北101曾經是世界最高建築，至今仍是台北最著名的地標。觀景台的360度台北全景、88樓的超快速電梯（每秒1010公尺）。', '全年適宜；跨年煙火12月31日是年度盛事',[('101觀景台（89F）','室內觀景台提供360度台北全景，天候好時可遠眺七星山和淡水河。'),('戶外天空殿堂（91F）','開放式觀景台，可以把手伸出欄杆拍照，風大但視野無敵。'),('超快速電梯','從1樓到89樓只需37秒，是世界最快電梯之一。'),('信義誠品','24小時營業的誠品書店，是台北最熱鬧的深夜文化地標。')],[('鼎泰豐信義店','小籠包的代名詞，皮薄汁多，每日排長隊。'),('八田与一奶茶','信義區人氣奶茶店，抹茶和original是最熱賣口味。'),('君品酒店下午茶','頂樓的下午茶可以邊吃邊看101夜景，浪漫指數破表。')],{'交通':'約200-500元','餐飲':'約1,500-3,000元','門票':'約800-1,000元','合計':'約2,500-4,500元'},[('門票多少錢？','成人全票約NT$600，學生約NT$500，網路預購常有優惠。'),('最佳參觀時間？','建議傍晚4-5點去，可以看到白天、日落和夜景三種景色。')])

add('tw-tainan-old','台南老街美食全攻略：從赤崁樓到擔仔麵，台灣食品之都的15家必吃店','tainan,old+street+food+taiwan',['台南','美食','歷史','老街'],'台南被CNN Travel評為世界十大最便宜美食城市第一名，也是台灣歷史最悠久的城市。', '全年適宜；每年農曆六月有王爺祭典',[('赤崁樓','台南最古老的建築，荷蘭殖民時期建造的普羅民遮城遺址，夜晚點燈後特別美麗。'),('延平街歷史街區','從開山路到民族路的老街，百年老宅與新銳咖啡廳並存。'),('大天后宮','台灣規模最大的媽祖廟，金碧輝煌的建築令人嘆為觀止。'),('四草綠色隧道','乘竹筏穿過紅樹林隧道，是台南最獨特的生態旅遊體驗。')],[('林生擔仔麵','百年老店擔仔麵，湯頭濃郁是台南代表性味道。'),('國華街蝦捲','現炸蝦捲，外皮酥脆內餡鮮甜。'),('開基杯杯魷','赤崁樓旁的碗仔魷，酸辣湯頭配上鮮嫩魷魚。'),('王家肉粽','台南肉粽代表，糯米香Q、醬汁入味。')],{'交通':'約300-600元','餐飲':'約1,500-3,000元','門票':'約200-400元','合計':'約2,000-4,000元'},[('適合幾天的行程？','兩天一夜剛好可以吃完主要美食，三天則可深入探索。'),('有什麼需要注意的？','夏季非常炎熱，請準備防曬用品；部分老店只收現金。')])

add('tw-yangmingshan','陽明山國家公園全攻略：火山地形、竹子湖海芋季與好母咖啡','yangmingshan,taipei+taiwan+volcano',['陽明山','台灣','自然景观','台北'],'陽明山國家公園是台灣第一個國家公園，擁有豐富的火山地形、溫泉和花海。竹子湖的海芋季（4-5月）和陽明花朝（3月）是每年最盛大的活動。', '3月花朝、4-5月海芋季、11-1月賞芒花',[('小油坑','陽明山最著名的火山口遺跡，硫磺煙氣裊裊，是新手登山者的首選目的地。'),('竹子湖海芋農園','每年4-5月海芋盛開，白色花朵在綠色田野間格外療癒。'),('好母咖啡','竹子湖入口处的标志性咖啡馆，手工鬆餅和海芋拿鐵是必點。'),('梦幻湖','火山口形成的湖泊，環湖步道全長1.3公里。')],[('海芋咖啡廳','竹子湖周邊的咖啡廳，海芋拿鐵和抹茶甜點是必點。'),('好母咖啡手工鬆餅','现烤鬆餅配上當地蜂蜜。'),('溫泉蛋','小油坑附近的溫泉蛋，用天然硫磺泉煮熟。')],{'交通':'約200-500元','餐飲':'約1,000-2,000元','門票':'免費','合計':'約1,500-3,000元'},[('怎麼去陽明山？','從台北捷運劍潭站搭紅36或260公車約20分鐘；或自行開車經陽明山公路。')])

add('tw-lanyu','蘭嶼环岛自驾攻略：紅頭漁港、朗島贝壳沙灘與達悟族地下屋文化','lanyu,orchid+island+taiwan',['蘭嶼','台東','原住民','離島'],'蘭嶼是達悟族的故鄉，以地下屋、飛魚季和碧海藍天聞名。這個距離台灣東岸僅20公里的小島，保留了最純粹的原住民文化和自然生態。', '5-10月（航運正常）；4月和9-10月是飛魚季',[('紅頭漁港','蘭嶼的主要港口，日出時分的漁船歸港景色是攝影師的最愛。'),('朗島贝壳沙灘','由珊瑚和貝殼碎屑組成的白色沙灘，潮間帶有豐富的海洋生物。'),('野銀古老部落','蘭嶼最古老的達悟部落，傳統家屋和石板屋保存完好。'),('黑沙海灘','蘭嶼最著名的黑色沙灘，沙粒細膩如粉末。')],[('飛魚料理','達悟族特有的飛魚季料理，烤飛魚配小米酒是年度盛典。'),('紅頭海鮮市场','每天早上新鮮漁獲直銷，生魚片和螃蟹是最受歡迎的選擇。'),('达悟族小米酒','蘭嶼特產的糯米酒，甘甜微醺。')],{'交通':'約4,000-8,000元','餐飲':'約2,000-3,500元','住宿':'約3,000-6,000元','合計':'約9,000-18,000元'},[('怎麼去蘭嶼？','從台東飛機場搭東航或立榮航空約25分鐘；或搭船約2-3小時。'),('需要預約嗎？','飛彈季（4-6月）和暑假期間住宿緊張，建議提前1個月預約。')])

add('tw-chiayi','嘉義奮起湖＆竹崎親水公園：阿里山森林鐵路與木製工藝全攻略','chiayi,fenchihu+japan',['嘉義','阿里山','森林','鐵路'],'嘉義是台灣最美的森林鐵路所在地，奮起湖的中式建築和竹崎親水公園的觀景平台，构成嘉義最迷人的旅遊風景。', '全年適宜；櫻花季2-3月、枫叶季11-12月',[('奮起湖老街','海拔1,400公尺的山間小鎮，日式建築老街和便當是不可錯過的體驗。'),('竹崎親水公園','嘉陽線列車經過的觀景平台，可以拍到火車穿過竹林的經典畫面。'),('阿里山森林鐵路','從嘉義到奮起湖的百年鐵路，沿途森林生態豐富。')],[('奮起湖便當','木桶裝的鐵路便當，爌肉飯配筍子是和台灣鐵路文化的經典組合。'),('竹崎火雞肉飯','嘉義特產的火雞肉飯，皮脆肉嫩汁多。'),('梅山鄉石猴茶','阿里山區的烏龍茶，茶葉香氣濃厚回甘。')],{'交通':'約1,500-3,000元','餐飲':'約1,500-2,500元','門票':'約800-1,200元','合計':'約4,000-7,000元'},[('森林鐵路需要預約嗎？','熱門時段（週末、連續假期）建議提前3-7天購票。')])

add('tw-nan-tou','南投日月潭＆清境農場：台灣中部最浪漫的湖泊與高山草原','nanto,ming+taiwan+lalu',['南投','日月潭','清境','農場'],'日月潭是台灣最美的湖泊，清境農場則是台灣最接近瑞士風光的度假勝地。', '3-4月櫻花季、9-11月清爽季節',[('日月潭環湖公路','32公里環湖公路，沿途有向山遊客中心、玄光寺、德化社等景點。'),('邵族文化園區','日月潭唯一的原住民邵族，了解他們的傳統文化和捕魚方式。'),('清境小瑞士花園','高山上的歐式庄园，綿羊悠閒吃草，彷彿置身歐洲阿尔卑斯山。')],[('環湖路肉圓','日月潭畔的百年老店，皮Q餡香是台灣人最愛的早餐。'),('清境紅藜麥料理','高山上種植的紅藜麥，營養價值高。'),('南投茶葉','凍頂烏龍是南投特產，霧峰鹿谷的茶園可提供品茶體驗。')],{'交通':'約1,500-3,000元','餐飲':'約2,000-3,500元','門票':'約1,000-2,000元','合計':'約4,500-9,000元'},[('日月潭和清境遠嗎？','相距約30分鐘車程，建議自駕或包車前往。')])

# EUROPE
add('eu-paris','巴黎三天兩夜全攻略：鐵塔、羅浮宮、蒙馬特与塞納河遊船','paris,eiffel+tower+louvre+france',['巴黎','法國','景點','美食'],'巴黎是世界上最浪漫的都市，埃菲爾鐵塔、羅浮宮、蒙馬特高地，每一處都是明信片級的美景。', '4-6月（櫻花季）和9-10月（秋季）',[('埃菲爾鐵塔','巴黎最標誌性的建築，建議預購頂樓門票，日落前30分鐘上塔可以看到雙色夜景。'),('羅浮宮','世界最大博物館，蒙娜麗莎、維納斯和勝利女神是三大鎮館之寶。'),('蒙馬特高地','聖心大教堂是蒙馬特地標，四周藝術家廣場是巴黎最獨特的街頭風景。'),('塞納河遊船','Bateaux Mouches或Bateaux Parisiens，晚餐船遊是浪漫夜晚的完美結束。')],[('馬卡龍','Ladurée和Pierre Hermé是最受歡迎的馬卡龍品牌。'),('可頌與咖啡','任何街角的麵包店都有最好的可頌。'),('法式焗蠔','巴黎左岸的經典料理。')],{'交通':'約2,000-4,000元','餐飲':'約4,000-8,000元','門票':'約2,000-4,000元','合計':'約8,000-16,000元'},[('巴黎地鐵安全嗎？','整體安全，但要注意扒手，尤其在熱門景點和地鐵站。')])

add('eu-rome','羅馬四日遊：斗獸場、特雷維噴泉與梵蒂岡museum完整攻略','rome,colosseum+vatican+italy',['羅馬','義大利','歷史','景點'],'羅馬是永恒之城，斗獸場、萬神殿、特雷維噴泉見證了兩千年的歷史。梵蒂岡museum收藏了人類最偉大的藝術品。', '4-6月和9-10月',[('斗獸場','古羅馬最壯觀的建築，內部結構和地下通道導覽非常有趣。'),('特雷維噴泉','拋硬幣的傳說：一枚硬幣讓你重返羅馬，三枚讓你找到愛情。深夜去人最少。'),('萬神殿','保存最完好的古羅馬建築，圓頂設計影響了整個西方建築史。'),('梵蒂岡博物館','西斯汀禮拜堂的天頂畫是米開朗基羅的巔峰之作。')],[('Cacio e Pepe','羅馬四大pasta之首，起司和黑胡椒的完美平衡。'),('Carbonara','培根蛋黃醬汁義大利麵，羅馬人的驕傲，不要加奶油！'),('Gelato','Giolitti和Fatamorgana是最受歡迎的義式冰淇淋。')],{'交通':'約1,500-3,000元','餐飲':'約3,000-6,000元','門票':'約2,000-3,500元','合計':'約6,500-12,500元'},[('羅馬安全嗎？','主要景點區域很安全，但要注意小偷，特別是在地鐵和火車站。')])

add('eu-amsterdam','阿姆斯特丹一日遊：運河、梵高博物館與花市完整攻略','amsterdam,canal+museum+netherlands',['阿姆斯特丹','荷蘭','博物館','運河'],'阿姆斯特丹是世界上最適合騎自行車的城市，運河環繞的古城風貌、世界級的博物館群。', '4月中旬庫肯霍夫花季；5-9月天气最好',[('運河環線','UNESCO世界遺產，乘船遊覽是最舒適的認識阿姆斯特丹方式。'),('梵高博物館','收藏全球最大的梵高作品，向日葵和星夜原作必看。需提前1-2週預訂門票。'),('花市（Bloemenmarkt）','世界上唯一的水上浮動花市，郁金香球根是必買伴手禮。'),('安妮之家','二戰期間安妮·法蘭克藏身的大樓。')],[('Haring','生吃新鮮鯡魚，加蔥花和酸黄瓜。'),('Stroopwafel','薄脆餅乾夾著焦糖syrup，現做的最美味。'),('Panenkoop','24小時營業的荷蘭薄餅店。')],{'交通':'約1,500-3,000元','餐飲':'約2,500-5,000元','門票':'約2,000-4,000元','合計':'約6,000-12,000元'},[('博物館門票需要預約嗎？','梵高博物館和安妮之家強烈建議提前預約，否則可能排3小時以上隊伍。')])

add('eu-london','倫敦四天遊：大笨鐘、大英博物館與白金漢宮完整攻略','london,big+ben+buckingham+uk',['倫敦','英國','景點','博物館'],'倫敦是世界上最多元化的城市之一，從皇家遺產到街頭藝術，從古典博物館到現代商場。', '5-9月氣候最宜人；12月聖誕市集最有氣氛',[('大笨鐘與國會大廈','倫敦最標誌性的建築，建議從威斯敏斯特橋拍攝完整倒影。'),('大英博物館','免費入場，埃及館、希臘館和羅塞塔石碑是必看展品。建議預留4小時以上。'),('白金漢宮換哨儀式','每天上午11點舉行，建議提前30分鐘占位置。'),('倫敦眼','泰晤士河畔的摩天輪，日落時分的景色最值得體驗。')],[('魚與薯條','British Nation Favorite，Golden Fritter和Poppies是倫敦最受歡迎的店。'),('英式下午茶','The Ritz或Sketch的下午茶是倫敦最經典的體驗。'),('Borough Market','倫敦最古老的食物市場。')],{'交通':'約2,000-4,000元','餐飲':'約4,000-8,000元','門票':'約2,000-4,000元','合計':'約8,000-16,000元'},[('需要簽證嗎？','台灣护照可免簽入境英國90天。')])

add('eu-barcelona','巴塞隆納四天遊：聖家堂、哥特区與畢卡索博物館完整攻略','barcelona,sagrada+familia+spain',['巴塞隆納','西班牙','高第','景點'],'巴塞隆納是西班牙最具魅力的城市，高第的建築奇觀、哥特區的古老街道、蘭布拉大道的熱鬧街景。', '4-6月和9-10月',[('聖家堂','高第的畢生代表作，至今仍在建設中。建議預購門票並參加導覽。'),('哥特區','中世紀的街道和建築，巴賽隆納最古老的區域，隱藏著無數秘密。'),('畢卡索博物館','收藏畢卡索早期作品，藍色時期的代表作必看。'),('巴特略之家','高第的另一個代表作，波浪形的外牆和彩色馬賽克令人驚嘆。')],[('Tapas','巴塞隆納的Tapas文化是最道地的用餐方式。'),('Paella','西班牙海鮮飯發源地，El Born區的La Marina是最受歡迎的店。'),('Jamón Ibérico','伊比利火腿是西班牙國寶級美食。')],{'交通':'約1,500-3,000元','餐飲':'約3,000-6,000元','門票':'約2,000-4,000元','合計':'約6,500-13,000元'},[('巴塞隆納安全嗎？','蘭布拉大道和地鐵要注意扒手，其他區域很安全。')])

# OCEANIA
add('oce-queenstown','紐西蘭皇后鎮四天遊：蹦極發源地、天空纜車與米尔福德峽灣','queenstown,new+zealand+adventure',['皇后鎮','紐西蘭','冒險','自然'],'皇后鎮是紐西蘭的冒險之都，世界第一個商業蹦極就發源地於此。壯麗的山景、清澈的湖水和豐富的水上活動。', '12-2月（夏季）適合徒步和水上活動；6-8月適合滑雪',[('天空纜車','上山俯瞰瓦卡蒂普湖和南阿爾卑斯山的絕佳角度。'),('劍橋空中纜車','世界最陡的纜車之一，通往凱羅納山頂。'),('峽灣航空巡航','直升機飛越峽灣的景观壯麗，比坐船更震撼。'),('箭鎮','19世紀淘金時代的遺址，保存完整的木造建築。')],[('Fergburger','皇后鎮最出名的漢堡店，常常排長隊但絕對值得。'),('紐西蘭羊肉','紐西蘭羊肉質地柔軟，沒有羶味。'),('Longrain餐廳','融合亞洲風味的紐西蘭料理。')],{'交通':'約3,000-6,000元','餐飲':'約3,000-5,000元','活動':'約4,000-8,000元','合計':'約10,000-20,000元'},[('蹦極安全嗎？','紐西蘭的蹦極標準是世界上最嚴格的，安全記錄極佳。')])

add('oce-sydney','悉尼四天遊：歌劇院、沙灘與岩石區美食完整攻略','sydney,opera+house+australia',['悉尼','澳洲','景點','美食'],'悉尼是澳洲最大的城市，歌劇院和海港大橋是世界上最知名的地標。邦迪海灘的衝浪文化、岩石區的歷史風情。', '12-2月（夏季）海灘季節；3-5月和9-11月氣候舒適',[('悉尼歌劇院','世界遺產建築，建議參加導覽並預購門票觀看一場演出。'),('邦迪海灘','悉尼最知名的海灘，1.5公里海岸線適合衝浪和日光浴。'),('岩石區','悉尼最古老的社區，cobblestone街道和歷史建築充滿歐洲風情。'),('達令港','夜景迷人，週末有夜市和街頭表演。')],[('悉尼魚市場','南半球最大的魚市場，新鮮生蠔和蟹是必吃。'),('Meat Market','岩石區的和牛專門店，澳洲和牛品質是世界級。'),('Bourke Street Bakery','悉尼最著名的麵包店，檸檬漿甜點是全球首創。')],{'交通':'約2,000-4,000元','餐飲':'約4,000-7,000元','門票':'約2,000-3,500元','合計':'約8,000-15,000元'},[('需要簽證嗎？','台灣护照需申請澳洲電子簽證（ETA），可線上申請。')])

# Generate all articles
count = 0
for slug in existing:
    if slug in RICH_DATA:
        title, keywords, tags, intro, best_season, attractions, food, budget, faq = RICH_DATA[slug]
    else:
        # Fallback for articles not in rich data
        region = get_region(slug)
        city = get_city(slug)
        title = f'{city}旅遊全攻略：{REGION_NAME.get(region,"該地區")}必訪景點與美食推薦'
        keywords = f'{region},{city.lower()}'
        tags = [region, city, '一日遊', '景點']
        intro = f'{city}是{REGION_NAME.get(region,"該地區")}最受歡迎的旅遊城市之一。'
        best_season = '春季（3-5月）和秋季（9-11月）是最適合旅遊的季節'
        attractions = [(f'{city}著名景點', '建議預留2-3小時深度遊覽。')]
        food = [(f'{city}在地美食', '價格親民又美味。')]
        budget = {'交通': f'約500-1500元', '餐飲': f'約1000-3000元', '合計': f'約2000-5000元'}
        faq = [('交通便利嗎？', '該地區公共交通發達。')]
    
    html = generate_html(slug, title, keywords, tags, intro, best_season, attractions, food, budget, faq)
    filepath = os.path.join(ARTICLES_DIR, f'{slug}.html')
    with open(filepath, 'w', encoding='utf-8') as f:
        f.write(html)
    count += 1
    if count % 10 == 0:
        print(f'Updated {count}/{len(existing)} articles...')

print(f'Done! Updated {count}/{len(existing)} articles with rich E-E-A-T content.')
